function adjustStyle() {
	screenWidthCurs = parseInt($(this).width());

	if (  ( vistaOrd && screenWidthCurs < limitPantallaTablet ) ||
 			( vistaTablet && (screenWidthCurs >= limitPantallaTablet || screenWidthCurs < limitPantallaMovil)  ) ||
			( vistaMov && screenWidthCurs > limitPantallaMovil )
		) {

		if (screenWidthCurs >= limitPantallaTablet) vistaOrd = true;
		else if (screenWidthCurs < limitPantallaTablet && screenWidthCurs >= limitPantallaMovil) vistaTablet = true;
		else if (screenWidthCurs <= limitPantallaMovil) vistaMov = true;
		mostrarBlocFiltres();
		mostrarPerfilsProfessionals();
		mostrarCursosFiss();
		mostrarTastets();
	}

	if (screenWidthCurs < 575) {
		$('.prisma-footer .panel').css('display', 'none');
		$('.accordion-footer').removeClass('active');
		$('.accordion-footer').click(function() {
			this.classList.toggle("active");
			var panel = this.nextElementSibling;
			if (panel.style.display === "block") {
				panel.style.display = "none";
				panel.style.maxHeight = null
			} else {
				panel.style.display = "block";
				panel.style.maxHeight = panel.scrollHeight + "px"
			}
		})
	}
	else {
		$('.accordion-footer').removeClass('active');
		$('.prisma-footer .panel').css('display', 'block')
	}
}

window.onscroll = function() {
	noPerdreHeader()
};
noPerdreHeader();

function noPerdreHeader() {
	var marginTop;
	if (document.body.scrollTop > 0 || document.documentElement.scrollTop > 0) {
		$('.top-menu').slideUp( "400", function() {
			// marginTop = $('header').css();
			$('#top-menu').css('display', 'none');
			$('#nav-header').css('position', 'fixed');
			marginTop = parseInt($('header').height());
			$('.prisma-container').css('margin-top', marginTop + 'px');
	  });
		$('#nav-header').css('top', '0');
	}
	else {

		if (!(/Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent))) {
			marginTop = (parseInt($('header').height()) + 13) +  (parseInt($('.top-menu').height()) + 8);
			$('#nav-header').css('top', '32px');
			$('.top-menu').slideDown( "400", function() {});
		}
		else {
			marginTop = parseInt($('header').height());
		}
		$('.prisma-container').css('margin-top', marginTop + 'px');
		$('#nav-header').css('position', 'absolute')
	}
}
